package glitch

import data.glitch_lib

# Download/URL source attributes without integrity verification
download_indicators := {"url", "source", "uri", "location", "endpoint", "download", "fetch", "pull", "get"}
integrity_indicators := {"checksum", "sha256", "md5", "hash", "digest", "verify", "validation", "integrity", "signature", "sign"}

# Container image attributes
image_indicators := {"image", "container_image", "docker_image"}
image_integrity := {"digest", "sha256", "immutable", "content_addressable"}
floating_tags := {"latest", "stable", "nightly", "beta", "alpha", "dev", "edge", "rc", "snapshot"}

# Protocol indicators for insecure transports
insecure_protocols := {"http", "ftp", "tftp", "telnet", "smtp"}
secure_indicators := {"https", "tls", "ssl", "verify_ssl", "verify_peer", "ca_cert", "client_cert"}

# Verification bypass flags
bypass_flags := {"allow_unauthenticated", "trusted", "insecure_skip_verify", "gpgcheck", "repo_gpgcheck", "verify"}

has_integrity_verification(attrs) {
    some attr in attrs
    attr.name == integrity_indicators[_]
}

has_secure_protocol(attrs) {
    some attr in attrs
    attr.name == "protocol"
    attr.value.ir_type == "String"
    attr.value.value == secure_indicators[_]
}

has_verification_bypass(attrs) {
    some attr in attrs
    attr.name == bypass_flags[_]
    attr.value.ir_type == "Boolean"
    attr.value.value == false
}

image_has_digest(attrs) {
    some attr in attrs
    attr.name == image_integrity[_]
}

image_floating_tag(attrs) {
    some attr in attrs
    attr.name == "tag"
    attr.value.ir_type == "String"
    tag := lower(attr.value.value)
    tag == floating_tags[_]
}

# Check for remote artifact retrieval without integrity verification
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    some attr in attrs
    attr.name == download_indicators[_]

    not has_integrity_verification(attrs)
    not has_secure_protocol(attrs)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing integrity verification for remote artifact retrieval - Data transmission lacks proper integrity checks. (CWE-353)"
    }
}

# Check for container images without digest/immutable reference
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    some attr in attrs
    attr.name == image_indicators[_]

    not image_has_digest(attrs)
    image_floating_tag(attrs)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Container image without immutable reference - Using floating tags instead of digest-based references. (CWE-353)"
    }
}

# Check for insecure protocol usage without verification
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    some attr in attrs
    attr.name == "protocol"
    attr.value.ir_type == "String"
    lower(attr.value.value) == insecure_protocols[_]

    not has_integrity_verification(attrs)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Insecure protocol without integrity verification - Data transmission over unencrypted channel lacks integrity checks. (CWE-353)"
    }
}

# Check for explicit verification bypass
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    has_verification_bypass(attrs)

    result := {
        "type": "sec_no_int_check",
        "element": node,
        "path": parent.path,
        "description": "Integrity verification explicitly disabled - Security check bypassed for data transmission or package installation. (CWE-353)"
    }
}

