package glitch

import data.glitch_lib

# Download/URL source attributes without integrity verification
download_indicators := {"url", "source", "uri", "location", "endpoint", "download", "fetch", "pull", "get"}
integrity_indicators := {"checksum", "sha256", "md5", "hash", "digest", "verify", "validation", "integrity", "signature", "sign"}

# Container image attributes
image_indicators := {"image", "container_image", "docker_image"}
image_integrity := {"digest", "sha256", "immutable", "content_addressable"}
floating_tags := {"latest", "stable", "nightly", "beta", "alpha", "dev", "edge", "rc", "snapshot"}

# Protocol indicators for insecure transports
insecure_protocols := {"http://", "ftp://", "tftp://", "telnet://"}

# Verification bypass flags - check for disabled verification
bypass_flags := {"allow_unauthenticated", "trusted", "insecure_skip_verify", "gpgcheck", "repo_gpgcheck", "verify_ssl", "verify_peer", "validate_certs", "ssl_verify"}

# Collect all nested values from a structure (flatten Hash, Array, etc.)
collect_values(value) = values {
    value.ir_type == "Hash"
    values := {v | some pair in value.value; collect_values(pair.value)[v]}
}

collect_values(value) = values {
    value.ir_type == "Array"
    values := {v | some elem in value.value; collect_values(elem)[v]}
}

collect_values(value) = {value} {
    not value.ir_type in {"Hash", "Array"}
}

# Check if any value contains insecure protocol
has_insecure_protocol(value) {
    some v in collect_values(value)
    v.ir_type == "String"
    protocol := lower(v.value)
    startswith(protocol, insecure_protocols[_])
}

# Check if verification is disabled (0, false, "no", "false")
is_verification_disabled(value) {
    value.ir_type == "Integer"
    value.value == 0
}

is_verification_disabled(value) {
    value.ir_type == "Boolean"
    value.value == false
}

is_verification_disabled(value) {
    value.ir_type == "String"
    lower(value.value) in {"no", "false", "0", "off", "disabled"}
}

# Walk through all nested structures to find KeyValue pairs with verification flags disabled
find_bypass_in_value(value, path) = results {
    value.ir_type == "Hash"
    results := {r |
        some pair in value.value
        pair.key.ir_type == "String"
        pair.key.value == bypass_flags[_]
        is_verification_disabled(pair.value)
        r := {"name": pair.key.value, "value": pair.value, "path": path}
    }
}

find_bypass_in_value(value, path) = results {
    value.ir_type == "Hash"
    results := {r |
        some pair in value.value
        nested := find_bypass_in_value(pair.value, array.concat(path, [pair.key.value]))
        r := nested[_]
    }
}

find_bypass_in_value(value, path) = results {
    value.ir_type == "Array"
    results := {r |
        some i, elem in value.value
        nested := find_bypass_in_value(elem, array.concat(path, [sprintf("[%d]", [i])]))
        r := nested[_]
    }
}

find_bypass_in_value(value, path) = set() {
    not value.ir_type in {"Hash", "Array"}
}

# Check all attributes and nested structures for verification bypass
has_verification_bypass_in_attrs(attrs) {
    some attr in attrs
    bypass := find_bypass_in_value(attr.value, [attr.name])
    count(bypass) > 0
}

# Check variables for verification bypass
has_verification_bypass_in_vars(vars) {
    some var in vars
    bypass := find_bypass_in_value(var.value, [var.name])
    count(bypass) > 0
}

# Check nested Hash structures for integrity indicators
has_integrity_in_hash(hash) {
    some pair in hash.value
    pair.key.ir_type == "String"
    pair.key.value == integrity_indicators[_]
}

has_integrity_in_value(value) {
    value.ir_type in {"String", "VariableReference"}
    # Check if key name suggests integrity
    false
}

has_integrity_in_value(value) {
    value.ir_type == "Hash"
    has_integrity_in_hash(value)
}

# Check if attribute has download indicator name with http and no integrity
is_insecure_download_attr(attr) {
    attr.name == download_indicators[_]
    some v in collect_values(attr.value)
    v.ir_type == "String"
    lower(v.value) == insecure_protocols[_]
}

# Main rule: Check for remote downloads over insecure protocols without integrity verification
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check atomic units
    atomic_units := glitch_lib.all_atomic_units(parent)
    some node in atomic_units

    attrs := glitch_lib.all_attributes(node)
    some attr in attrs

    # Find download-related attributes with insecure protocols
    attr.name == download_indicators[_]
    some v in collect_values(attr.value)
    v.ir_type == "String"
    val := lower(v.value)
    startswith(val, insecure_protocols[_])

    # Check no integrity verification present in this atomic unit
    not some int_attr in attrs; int_attr.name == integrity_indicators[_]

    result := {
        "type": "sec_no_int_check",
        "element": node,
        "path": parent.path,
        "description": "Missing integrity verification for remote artifact retrieval over insecure protocol - Data transmission lacks proper integrity checks. (CWE-353)"
    }
}

# Rule: Check for container images using floating tags without digest
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    atomic_units := glitch_lib.all_atomic_units(parent)
    some node in atomic_units

    attrs := glitch_lib.all_attributes(node)
    some attr in attrs

    # Check for image attribute
    attr.name == image_indicators[_]
    some v in collect_values(attr.value)
    v.ir_type == "String"

    # Check if contains floating tag
    val := lower(v.value)
    contains(val, ":")
    not contains(val, "@sha256")
    not contains(val, "@digest")
    parts := split(val, ":")
    count(parts) == 2
    tag := parts[1]
    floating_tags[tag]

    # Check no digest attribute present
    not some int_attr in attrs; int_attr.name == image_integrity[_]

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Container image without immutable reference - Using floating tags instead of digest-based references. (CWE-353)"
    }
}

# Rule: Check for explicit verification bypass in atomic unit attributes
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    atomic_units := glitch_lib.all_atomic_units(parent)
    some node in atomic_units

    attrs := glitch_lib.all_attributes(node)

    # Check for direct verification bypass attributes
    some attr in attrs
    attr.name == bypass_flags[_]
    is_verification_disabled(attr.value)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Integrity verification explicitly disabled - Security check bypassed for data transmission or package installation. (CWE-353)"
    }
}

# Rule: Check for verification bypass in nested Hash structures (variables, complex attributes)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check in variables
    vars := {v | walk(parent, [_, v]); v.ir_type == "Variable"}
    some var in vars

    bypass := find_bypass_in_value(var.value, [var.name])
    some b in bypass

    result := {
        "type": "sec_no_int_check",
        "element": b.value,
        "path": parent.path,
        "description": "Integrity verification explicitly disabled in variable configuration - Security check bypassed for data transmission or package installation. (CWE-353)"
    }
}

# Rule: Check for verification bypass in atomic unit nested attributes
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    atomic_units := glitch_lib.all_atomic_units(parent)
    some node in atomic_units

    attrs := glitch_lib.all_attributes(node)
    some attr in attrs

    bypass := find_bypass_in_value(attr.value, [attr.name])
    some b in bypass

    result := {
        "type": "sec_no_int_check",
        "element": b.value,
        "path": parent.path,
        "description": "Integrity verification explicitly disabled in nested configuration - Security check bypassed for data transmission or package installation. (CWE-353)"
    }
}

